import fs from 'fs';
import {
  generateChunkPass1,
  generateChunkPass2,
} from '../src/utils/chunkGenerator.js';
import { buildGreedyArrays } from '../src/utils/greedyMesh.js';

// Setup mock globals
global.window = {};

const cx = 0;
const cz = 0;
const seed = 12345;

try {
  const pass1 = generateChunkPass1(cx, cz, seed);
  console.log(
    'Pass 1 completed. Highest surface block:',
    pass1.getSurfaceHeightMap[0]
  );

  const packedBuffer = new Uint32Array(pass1.buffer);
  const { buffer: newBuffer, overflow } = generateChunkPass2(
    cx,
    cz,
    packedBuffer,
    pass1.getSurfaceHeightMap,
    seed
  );

  console.log('Pass 2 completed. Checking for Flora in buffer...');
  let floraFound = 0;
  for (let i = 0; i < newBuffer.length; i++) {
    const val = newBuffer[i];
    const tex = val & 0xff;
    if (tex === 15 || tex === 16 || tex === 17) {
      floraFound++;
    }
  }
  console.log(`Found ${floraFound} flora blocks in chunk buffer!`);

  console.log('Running Greedy Mesher...');
  const meshArrays = buildGreedyArrays(newBuffer, cx, cz, []);

  const floraArr = meshArrays.__flora;
  console.log(
    `Flora Float32Array length: ${floraArr.length}. Instances: ${floraArr.length / 6}`
  );

  if (floraArr.length > 0) {
    console.log('First Flora Instance Data:');
    console.log(`  X: ${floraArr[0]}`);
    console.log(`  Y: ${floraArr[1]}`);
    console.log(`  Z: ${floraArr[2]}`);
    console.log(`  BlockId: ${floraArr[3]}`);
    console.log(`  SunLight: ${floraArr[4]}`);
    console.log(`  BlockLight: ${floraArr[5]}`);
  }
} catch (e) {
  console.error('Test failed:', e);
}

import {
  BlockRegistry,
  BlockIds,
  FaceMappings,
  TextureRegistry,
} from './src/registry/BlockRegistry.js';

const grassId = BlockIds['tall_grass'];
console.log('Tall Grass ID:', grassId);
const faceMapping = FaceMappings[grassId];
console.log('FaceMapping for Tall Grass:', faceMapping);
console.log('Texture Array Index:', faceMapping.top);
console.log(
  'Texture filename at that index:',
  TextureRegistry[faceMapping.top]
);

const vTexId = faceMapping.top;
const tileX = vTexId % 16;
const tileY = Math.floor(vTexId / 16);
console.log('Shader tileX:', tileX, 'tileY:', tileY);

import React, { useState } from 'react';
import TitleScreen from './components/ui/TitleScreen';
import GameEngine from './GameEngine';
import { ErrorBoundary } from './components/ErrorBoundary';
import CustomCursor from './components/ui/CustomCursor';
import { SpectorModal } from './components/ui/SpectorModal';

import { initWorldSeed } from './worldSeed';

export default function App() {
  if (!localStorage.getItem('v14_reload_fix')) {
    localStorage.setItem('v14_reload_fix', '1');
    window.location.reload();
  }

  const [gameState, setGameState] = useState('menu'); // 'menu' or 'playing'

  const handleStart = (slotId) => {
    sessionStorage.setItem('saveSlotId', slotId);
    initWorldSeed();
    setGameState('playing');
  };

  return (
    <>
      <CustomCursor />
      <ErrorBoundary>
        <SpectorModal />
      </ErrorBoundary>
      {gameState === 'menu' ? (
        <ErrorBoundary>
          <TitleScreen onStartNew={handleStart} onContinue={handleStart} />
        </ErrorBoundary>
      ) : (
        <ErrorBoundary>
          <GameEngine />
        </ErrorBoundary>
      )}
    </>
  );
}

import { useEffect, Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { Physics } from '@react-three/rapier';
import { Player } from './components/Player';
import { FPV } from './components/FPV';
import { Screenshot } from './components/Screenshot';
import { ViewModel } from './components/ViewModel';
import { Cubes } from './components/Cubes';
import { Hotbar } from './components/Hotbar';
import InGameUI from './components/ui/InGameUI';
import { Minimap } from './components/Minimap';
import { AmbientAudio } from './components/AmbientAudio';
import { AudioPoolManager } from './audio/AudioPoolManager';
import { AchievementPopup } from './components/AchievementPopup';
import { Crosshair } from './components/Crosshair';
import { DynamicSky } from './components/DynamicSky';
import { Enemies } from './components/Enemies';
import { Bullets } from './components/Bullets';
import { Lasers } from './components/Lasers';
import { Tether } from './components/Tether';
import * as THREE from 'three';
import { ErrorBoundary } from './components/ErrorBoundary';
import { GhostBlock } from './components/GhostBlock';
import { DroppedItems } from './components/DroppedItems';
import { Tombstones } from './components/Tombstones';
import { HostCombat } from './components/HostCombat';
import { DeathScreen } from './components/DeathScreen';
import { WeatherSystem } from './components/WeatherSystem';
import TitleScreen from './components/ui/TitleScreen';
import { ChunkManager } from './components/ChunkManager';
import { AutoSaveManager } from './components/AutoSaveManager';
import { LoadingScreen } from './components/LoadingScreen';
import { PostFX } from './components/PostFX';
import { Lantern } from './components/Flashlight';
import { Flares } from './components/Flares';
import { BlockInteraction } from './components/BlockInteraction';
import { MultiplayerManager } from './components/MultiplayerManager';
import { useStore } from './stores/useStore';
import { DebugOverlay } from './components/DebugOverlay';
import { DebugTracker } from './components/DebugTracker';
import { SpectorModal } from './components/ui/SpectorModal';
import { Waypoints } from './components/Waypoints';

const LiquidOverlay = () => {
  const submerged = useStore((state) => state.submergedLiquid);
  if (!submerged) return null;

  if (submerged === 'lava') {
    return (
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          background:
            'radial-gradient(circle, rgba(255,100,0,0.85) 0%, rgba(180,20,0,0.95) 60%, rgba(80,0,0,1.0) 100%)',
          opacity: 0.92,
          pointerEvents: 'none',
          zIndex: 40,
        }}
      />
    );
  }

  if (submerged === 'water') {
    return (
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          background:
            'linear-gradient(to bottom, rgba(14, 165, 233, 0.4) 0%, rgba(3, 105, 161, 0.7) 100%)',
          pointerEvents: 'none',
          zIndex: 40,
          mixBlendMode: 'color',
        }}
      />
    );
  }
  return null;
};

export default function GameEngine() {
  const isWorldReady = useStore((state) => state.isWorldReady);
  const hasLoadedState = useStore((state) => state.hasLoadedState);
  const loadPlayerState = useStore((state) => state.loadPlayerState);
  const loadAchievements = useStore((state) => state.loadAchievements);
  const renderDistance = useStore((state) => state.renderDistance);
  const incrementPlaytime = useStore((state) => state.incrementPlaytime);
  const debugPhysics = useStore((state) => state.debugPhysics);

  useEffect(() => {
    loadPlayerState();
    loadAchievements();
    window.__DEBUG_STORE__ = useStore;
  }, [loadPlayerState, loadAchievements]);

  useEffect(() => {
    if (hasLoadedState && isWorldReady) {
      const interval = setInterval(() => {
        incrementPlaytime();
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [hasLoadedState, isWorldReady, incrementPlaytime]);

  return (
    <>
      {(!isWorldReady || !hasLoadedState) && <LoadingScreen />}
      {hasLoadedState && (
        <>
          <DebugOverlay />
          <AchievementPopup />
          <AmbientAudio />
          <Crosshair />
          <Hotbar />

          <InGameUI />
          <DeathScreen />
          <Minimap />
          <LiquidOverlay />
          <SpectorModal />
          <ErrorBoundary>
            <Canvas
              id="main-webgl-canvas"
              shadows={{ type: THREE.PCFShadowMap }}
              dpr={[1, 1.5]}
              gl={{ antialias: false, powerPreference: 'high-performance' }}
              camera={{ fov: 75, near: 0.1, far: 10000 }}
              onCreated={({ gl }) => {
                gl.domElement.addEventListener(
                  'webglcontextlost',
                  (e) => {
                    e.preventDefault();
                    console.error(
                      '[GameEngine] WebGL Context Lost! The GPU driver crashed or the browser suspended the tab.'
                    );
                    alert(
                      'Graphics Engine crashed (WebGL Context Lost). The browser suspended the tab or ran out of VRAM. Press OK to restart the game.'
                    );
                    window.location.reload();
                  },
                  false
                );
              }}
            >
              <Suspense fallback={null}>
                <ChunkManager />
                <AudioPoolManager />
                <AutoSaveManager />
                <DebugTracker />
                {/* Fog density scales inversely with render distance */}
                <fogExp2
                  attach="fog"
                  args={['#301040', 1.0 / (renderDistance * 14)]}
                />
                <DynamicSky />
                <WeatherSystem />
                <FPV />
                <Physics
                  debug={debugPhysics}
                  gravity={[0, -30, 0]}
                  timeStep="vary"
                >
                  <Player />
                  <Cubes />
                  <Enemies />
                  <Bullets />
                  <Lasers />
                  <Tether />
                  <DroppedItems />
                  <Tombstones />
                  <HostCombat />
                </Physics>
                {/* {liveTracking.current && <EnvironmentMap />} */}
              </Suspense>
              <BlockInteraction />
              <ViewModel />
              <GhostBlock />
              <Flares />
              <MultiplayerManager />
              <Waypoints />
              <Lantern />
              <PostFX />
              <Screenshot />
            </Canvas>
          </ErrorBoundary>
        </>
      )}
    </>
  );
}

import React, { useRef, useMemo, useEffect } from 'react';
import { useThree, useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { gameAudio } from './GameAudio';

// Global reference so non-React components (like Zustand or imperative code) can request spatial audio
export let globalAudioPool = null;

export const AudioPoolManager = ({ poolSize = 15 }) => {
  const { camera } = useThree();
  const poolRef = useRef([]);

  useEffect(() => {
    // Initialize the GameAudioSystem with the camera so it can mount the AudioListener
    gameAudio.initialize(camera);
  }, [camera]);

  const voices = useMemo(() => {
    return Array.from({ length: poolSize }).map((_, i) => {
      const obj = new THREE.Object3D();
      return { id: i, obj, active: false, playing: false };
    });
  }, [poolSize]);

  useEffect(() => {
    globalAudioPool = {
      playSpatial: (
        soundName,
        positionArray,
        volume = 1.0,
        distanceParams = {}
      ) => {
        if (!gameAudio.initialized) return;

        // 1. Voice Culling (Concurrency)
        if (!gameAudio.canPlayVoice(soundName)) return;

        // 2. Distance Culling
        const distSq = camera.position.distanceToSquared(
          new THREE.Vector3(
            positionArray[0],
            positionArray[1],
            positionArray[2]
          )
        );
        const maxDist = distanceParams.maxDistance || 50;
        if (distSq > maxDist * maxDist) {
          gameAudio.releaseVoice(soundName);
          return;
        }

        // 3. Find available voice
        const voice = voices.find((v) => !v.active);
        if (!voice) {
          gameAudio.releaseVoice(soundName);
          return; // Pool exhausted
        }

        const buffer = gameAudio.getBuffer(soundName);
        if (!buffer) {
          gameAudio.releaseVoice(soundName);
          return;
        }

        voice.active = true;
        voice.soundName = soundName;
        voice.obj.position.set(
          positionArray[0],
          positionArray[1],
          positionArray[2]
        );

        // We create the PositionalAudio imperatively to attach it to the dummy Object3D
        if (!voice.audio) {
          voice.audio = new THREE.PositionalAudio(gameAudio.listener);
          voice.audio.setRefDistance(distanceParams.refDistance || 5);
          voice.audio.setMaxDistance(maxDist);
          voice.audio.setDistanceModel('linear');
          voice.audio.setRolloffFactor(1);
          voice.obj.add(voice.audio);

          // Connect to the SFX bus instead of directly to Master
          voice.audio.disconnect();
          voice.audio.connect(gameAudio.sfxGain);
        }

        // Randomize pitch to prevent machine-gunning
        voice.audio.setPlaybackRate(0.9 + Math.random() * 0.2);
        voice.audio.setVolume(volume);
        voice.audio.setBuffer(buffer);

        // Cleanup when finished
        voice.audio.onEnded = () => {
          voice.active = false;
          voice.playing = false;
          gameAudio.releaseVoice(soundName);
        };

        voice.audio.play();
        voice.playing = true;

        // Dynamic Ducking for heavy impacts
        if (soundName === 'explosion') {
          gameAudio.triggerDucking();
        }
      },
    };

    return () => {
      globalAudioPool = null;
    };
  }, [voices, camera]);

  return (
    <group>
      {voices.map((v) => (
        <primitive key={v.id} object={v.obj} />
      ))}
    </group>
  );
};

import React, { useEffect } from 'react';
import { useStore } from '../stores/useStore';
import { motion, AnimatePresence } from 'framer-motion';

export const AchievementPopup = () => {
  const recentAchievement = useStore((state) => state.recentAchievement);
  const clearRecentAchievement = useStore(
    (state) => state.clearRecentAchievement
  );

  useEffect(() => {
    if (recentAchievement) {
      const timer = setTimeout(() => {
        clearRecentAchievement();
      }, 4000);
      return () => clearTimeout(timer);
    }
  }, [recentAchievement, clearRecentAchievement]);

  return (
    <AnimatePresence>
      {recentAchievement && (
        <motion.div
          initial={{ y: -100, opacity: 0, x: '-50%' }}
          animate={{ y: 20, opacity: 1, x: '-50%' }}
          exit={{ y: -100, opacity: 0, x: '-50%' }}
          transition={{ type: 'spring', damping: 15, stiffness: 200 }}
          style={{
            position: 'absolute',
            top: 0,
            left: '50%',
            backgroundColor: 'rgba(30, 41, 59, 0.95)',
            border: '2px solid #fbbf24',
            borderRadius: '8px',
            padding: '12px 24px',
            display: 'flex',
            alignItems: 'center',
            gap: '16px',
            zIndex: 10000,
            boxShadow: '0 10px 25px rgba(0,0,0,0.5)',
            pointerEvents: 'none',
          }}
        >
          <div style={{ fontSize: '32px' }}>
            {recentAchievement.icon || '🏆'}
          </div>
          <div>
            <div
              style={{
                color: '#fbbf24',
                fontSize: '14px',
                fontWeight: 'bold',
                textTransform: 'uppercase',
                letterSpacing: '1px',
              }}
            >
              Achievement Get!
            </div>
            <div
              style={{
                color: '#fff',
                fontSize: '18px',
                fontFamily: 'monospace',
              }}
            >
              {recentAchievement.title}
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

