import { useEffect, useRef, useState } from 'react';
import { useStore } from '../stores/useStore';
import { gameAudio } from '../audio/GameAudio';

export const AmbientAudio = () => {
  const isRaining = useStore((state) => state.isRaining);
  const synthRef = useRef(null);
  const [audioReady, setAudioReady] = useState(false);

  useEffect(() => {
    if (gameAudio.initialized && gameAudio.context) {
      setAudioReady(true);
      return;
    }
    const interval = setInterval(() => {
      if (gameAudio.initialized && gameAudio.context) {
        setAudioReady(true);
        clearInterval(interval);
      }
    }, 500);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!audioReady) return;

    const ctx = gameAudio.context;

    // Create Rain Synthesizer (White Noise -> Lowpass Filters)
    const bufferSize = ctx.sampleRate * 2; // 2 seconds of noise
    const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);

    for (let i = 0; i < bufferSize; i++) {
      // White noise from -1 to 1
      output[i] = Math.random() * 2 - 1;
    }

    const noiseSource = ctx.createBufferSource();
    noiseSource.buffer = noiseBuffer;
    noiseSource.loop = true;

    // Filter 1: Lowpass for the deep rumble of rain
    const lowpass1 = ctx.createBiquadFilter();
    lowpass1.type = 'lowpass';
    lowpass1.frequency.value = 400;

    // Filter 2: Bandpass for the "pitter patter" high-end splash
    const bandpass = ctx.createBiquadFilter();
    bandpass.type = 'bandpass';
    bandpass.frequency.value = 3500;
    bandpass.Q.value = 1.0;

    // Filter 3: High-shelf to soften harsh digital highs
    const highShelf = ctx.createBiquadFilter();
    highShelf.type = 'highshelf';
    highShelf.frequency.value = 6000;
    highShelf.gain.value = -12;

    const rainGain = ctx.createGain();
    rainGain.gain.value = 0; // Start silent

    // Route: Noise -> Filters -> Gain -> SFX Bus
    noiseSource.connect(lowpass1);
    lowpass1.connect(rainGain);

    noiseSource.connect(bandpass);
    bandpass.connect(highShelf);
    highShelf.connect(rainGain);

    if (gameAudio.sfxGain) {
      rainGain.connect(gameAudio.sfxGain);
    } else {
      rainGain.connect(ctx.destination);
    }

    noiseSource.start(0);

    synthRef.current = {
      source: noiseSource,
      gain: rainGain,
      ctx: ctx,
    };

    return () => {
      try {
        noiseSource.stop();
      } catch (e) {}
      noiseSource.disconnect();
      lowpass1.disconnect();
      bandpass.disconnect();
      highShelf.disconnect();
      rainGain.disconnect();
    };
  }, [audioReady]);

  useEffect(() => {
    if (!synthRef.current) return;
    const { gain, ctx } = synthRef.current;

    // Check state of the WebAudio context (user gesture restriction)
    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const now = ctx.currentTime;
    // Fade in/out over 2 seconds
    gain.gain.cancelScheduledValues(now);

    if (isRaining) {
      gain.gain.setValueAtTime(gain.gain.value, now);
      gain.gain.linearRampToValueAtTime(0.3, now + 2.0); // Rain target volume
    } else {
      gain.gain.setValueAtTime(gain.gain.value, now);
      gain.gain.linearRampToValueAtTime(0.0, now + 2.0);
    }
  }, [isRaining, audioReady]);

  return null;
};

/**
 * BlockInteraction.jsx — Amanatides-Woo DDA raycaster for block picking.
 *
 * WHY DDA AND NOT MESH RAYCASTING:
 *   Greedy meshing merges many 1×1×1 blocks into one large triangle. If you
 *   use Three.js's built-in raycaster against those triangles (e.g. e.point +
 *   e.face.normal from onClick), you get the position on the giant merged quad
 *   — not the specific 1×1×1 block that was clicked.
 *
 *   The Amanatides-Woo DDA algorithm avoids this entirely. It fires a
 *   mathematical ray through the CPU block data grid (the same Map/object that
 *   the chunk renderer reads), stepping from block-boundary to block-boundary
 *   at O(distance) cost. The visual mesh is never touched.
 *
 * DDA COORDINATE SYSTEM:
 *   Our blocks use a standard convention: all block meshes occupy [bx, bx+1].
 *   Block at integer index (bx, by, bz) occupies the AABB:
 *     X: [bx, bx+1]   Y: [by, by+1]   Z: [bz, bz+1]
 *
 *   To find the block index from world coordinates, we simply floor them:
 *     ox = camera.x,  oy = camera.y,  oz = camera.z
 *   Then floor(ox) gives the block integer index bx.
 *
 * USAGE:
 *   Mount <BlockInteraction /> anywhere inside the R3F Canvas. It renders nothing.
 *   It drives setHoverTarget every frame and fires block actions on mousedown.
 */

import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import {
  BlockRegistry,
  BlockById,
  BlockKeyById,
} from '../registry/BlockRegistry';
import {
  getIndex,
  getTextureId,
  CHUNK_Y_MIN,
  CHUNK_Y_MAX,
} from '../utils/chunkData';
import { useStore } from '../stores/useStore';
import { useNetworkStore } from '../stores/useNetworkStore';
import { playerPosition } from '../globals';
import { gameAudio } from '../audio/GameAudio';
import { GlobalRegistry } from '../registry/Registry';

const MAX_REACH = 8; // blocks

// ── Amanatides-Woo Fast Voxel Traversal ──────────────────────────────────────
/**
 * @param {THREE.Vector3} origin   — ray start (camera world position)
 * @param {THREE.Vector3} dir      — unit direction vector
 * @param {number}        maxDist  — maximum distance in blocks
 * @param {Object}        chunks   — Zustand chunks map (chunkKey → {blocks})
 * @returns {{ block, bx, by, bz, face:[nx,ny,nz] } | null}
 *   block = the block data object that was hit
 *   bx/by/bz = block-centre world coords
 *   face = outward face normal of the hit face (the face the ray entered from)
 */
function castRayDDA(origin, dir, maxDist, chunks) {
  // ── Transform to DDA space ────────────────────────────────────────────────
  // No shifts needed. Block (ix,iy,iz) occupies [ix, ix+1].
  const ox = origin.x;
  const oy = origin.y;
  const oz = origin.z;
  const dx = dir.x,
    dy = dir.y,
    dz = dir.z;

  // Starting block index
  let ix = Math.floor(ox);
  let iy = Math.floor(oy);
  let iz = Math.floor(oz);

  // Step direction (±1 per axis)
  const stepX = dx >= 0 ? 1 : -1;
  const stepY = dy >= 0 ? 1 : -1;
  const stepZ = dz >= 0 ? 1 : -1;

  // tDelta: ray length to cross one full block in each axis
  const tDX = dx !== 0 ? Math.abs(1 / dx) : Infinity;
  const tDY = dy !== 0 ? Math.abs(1 / dy) : Infinity;
  const tDZ = dz !== 0 ? Math.abs(1 / dz) : Infinity;

  // tMax: initial distance to the next boundary in each axis
  let tmX = dx > 0 ? (ix + 1 - ox) * tDX : dx < 0 ? (ox - ix) * tDX : Infinity;
  let tmY = dy > 0 ? (iy + 1 - oy) * tDY : dy < 0 ? (oy - iy) * tDY : Infinity;
  let tmZ = dz > 0 ? (iz + 1 - oz) * tDZ : dz < 0 ? (oz - iz) * tDZ : Infinity;

  // The face normal we entered the CURRENT block through (outward from the block)
  // Starts as "no face" — the camera's starting block is checked first.
  let face = [0, 0, 0];

  // Maximum iterations guard (prevents infinite loop; maxDist+3 is more than enough)
  const maxSteps = Math.ceil(maxDist) * 3 + 10;

  for (let step = 0; step < maxSteps; step++) {
    // ── Look up block at current DDA cell ───────────────────────────────────
    const bx = ix; // block centre X  (integer)
    const by = iy; // block centre Y  (integer)
    const bz = iz; // block centre Z  (integer)

    const cx = Math.floor(bx / 16);
    const cz = Math.floor(bz / 16);
    const chunk = chunks[`${cx},${cz}`];
    if (chunk) {
      const lx = ((bx % 16) + 16) % 16;
      const lz = ((bz % 16) + 16) % 16;
      const ly = by; // Y is already integer block index
      if (ly >= CHUNK_Y_MIN && ly <= CHUNK_Y_MAX) {
        if (!chunk.buffer) {
          console.error('FATAL: chunk.buffer is undefined!', chunk);
          return null;
        }
        const val = chunk.buffer[getIndex(lx, ly, lz)];
        if (val !== undefined && val !== 0) {
          const tex = getTextureId(val);
          if (tex !== 0) {
            const blockDef = BlockById[tex];
            // Skip flora (invisible crossed-quads) and liquids — they are not
            // solid interactable blocks. The ray continues through them so the
            // player can click on the solid ground/block underneath.
            if (!blockDef?.isFlora && !blockDef?.isLiquid) {
              const block = { texture: BlockKeyById[tex], pos: [bx, by, bz] };
              return { block, bx, by, bz, face };
            }
          }
        }
      }
    }
    if (tmX < tmY) {
      if (tmX < tmZ) {
        if (tmX > maxDist) return null;
        ix += stepX;
        tmX += tDX;
        face = [-stepX, 0, 0];
      } else {
        if (tmZ > maxDist) return null;
        iz += stepZ;
        tmZ += tDZ;
        face = [0, 0, -stepZ];
      }
    } else {
      if (tmY < tmZ) {
        if (tmY > maxDist) return null;
        iy += stepY;
        tmY += tDY;
        face = [0, -stepY, 0];
      } else {
        if (tmZ > maxDist) return null;
        iz += stepZ;
        tmZ += tDZ;
        face = [0, 0, -stepZ];
      }
    }
  }

  return null;
}

// ── Component ─────────────────────────────────────────────────────────────────
const _dir = new THREE.Vector3();

export const BlockInteraction = () => {
  const { camera } = useThree();

  const setHoverTarget = useStore((state) => state.setHoverTarget);
  const damageBlock = useStore((state) => state.damageBlock);
  const addCube = useStore((state) => state.addCube);

  // Last DDA result — updated every frame, consumed by mousedown handler
  const hitRef = useRef(null);
  const prevTargetKey = useRef(null); // "bx,by,bz" string — avoids calling setHoverTarget 60×/s

  // ── Fire DDA ray every frame for hover highlight ──────────────────────────
  useFrame(() => {
    camera.getWorldDirection(_dir);
    const chunks = useStore.getState().chunks;
    const hit = castRayDDA(camera.position, _dir, MAX_REACH, chunks);
    hitRef.current = hit;

    // Only call setHoverTarget when the targeted block CHANGES — not every frame.
    // Without this guard, GhostBlock re-renders at 60 fps even when stationary,
    // because Zustand notifies all subscribers on every setState call.
    const key = hit ? `${hit.bx},${hit.by},${hit.bz}` : null;
    if (key !== prevTargetKey.current) {
      prevTargetKey.current = key;
      setHoverTarget(hit ? [hit.bx, hit.by, hit.bz] : null);
    }
  });

  // ── Mouse click handler ────────────────────────────────────────────────────
  useEffect(() => {
    const onMouseDown = (e) => {
      // Only act when the pointer is locked (game is focused, UI is closed)
      if (!document.pointerLockElement) return;

      const hit = hitRef.current;
      if (!hit) return;
      const { block, bx, by, bz, face } = hit;
      const [nx, ny, nz] = face;

      // Handle Waypoint placement on Middle Mouse Click
      if (e.button === 1) {
        const { broadcastWaypoint } = useNetworkStore.getState();
        broadcastWaypoint(
          bx + 0.5 + nx * 0.5,
          by + 0.5 + ny * 0.5,
          bz + 0.5 + nz * 0.5
        );
        return;
      }

      // Only process left-click for building/breaking
      if (e.button !== 0) return;

      const state = useStore.getState();
      if (state.isUIActive && state.isUIActive()) return;

      const activeTexture = state.texture;

      // Intercept flare break
      if (block.texture === 'flare') {
        const flares = state.placedFlares;
        let flareId = null;
        for (let i = 0; i < flares.length; i++) {
          const vx = Math.floor(flares[i].pos[0] + flares[i].normal[0] * 0.1);
          const vy = Math.floor(flares[i].pos[1] + flares[i].normal[1] * 0.1);
          const vz = Math.floor(flares[i].pos[2] + flares[i].normal[2] * 0.1);
          if (vx === bx && vy === by && vz === bz) {
            flareId = flares[i].id;
            break;
          }
        }
        if (flareId) {
          state.removeFlare(flareId);
          gameAudio.playGlobal('break');
        } else {
          damageBlock(bx, by, bz, 100);
          gameAudio.playGlobal('break');
        }
        return;
      }

      // TNT always explodes, regardless of tool
      if (block.texture === 'tnt') {
        state.triggerExplosion(bx, by, bz);
        gameAudio.playGlobal('explosion');
        return;
      }

      if (e.altKey || activeTexture === 'pickaxe') {
        // Force-break (alt key) or pickaxe → high damage
        damageBlock(bx, by, bz, 100);
        gameAudio.playGlobal('break');
        if (block.texture === 'log') {
          useStore
            .getState()
            .unlockAchievement(
              'getting_wood',
              'Getting Wood',
              'Punch a tree until it breaks',
              '🪵'
            );
        }
      } else if (activeTexture === 'sword') {
        // Melee tool → moderate damage
        damageBlock(bx, by, bz, 35);
        gameAudio.playGlobal('break');
      } else if (
        activeTexture === 'gun' ||
        activeTexture === 'grapple' ||
        activeTexture === 'gauss_rifle'
      ) {
        // Ranged tools handled in Player.jsx, do NOT place blocks or melee
        return;
      } else if (activeTexture === 'flare') {
        // Place flare on the surface of the clicked face
        const placeX = bx + nx;
        const placeY = by + ny;
        const placeZ = bz + nz;
        state.placeFlare(
          [bx + 0.5 + nx * 0.5, by + 0.5 + ny * 0.5, bz + 0.5 + nz * 0.5],
          [nx, ny, nz],
          `${placeX},${placeY},${placeZ}`
        );
        gameAudio.playGlobal('place');
        state.consumeActiveItem();
      } else if (
        activeTexture === 'lantern' ||
        activeTexture === 'flashlight'
      ) {
        // Carried items — no block interaction
      } else {
        if (!activeTexture) return; // Prevent empty hand from placing dirt!

        const registryItem = GlobalRegistry[activeTexture];
        if (registryItem && registryItem.type === 'tool') return;

        // Building block selected — place it adjacent to the hit face.
        const px = bx + nx;
        const py = by + ny;
        const pz = bz + nz;

        // Prevent placing block inside the player's physical hitbox
        const blockY = py; // py is now a pure integer
        const pPos = [playerPosition.x, playerPosition.y, playerPosition.z]; // [x, y, z] center of player capsule
        const intersects =
          pPos[0] + 0.4 > px &&
          pPos[0] - 0.4 < px + 1 &&
          pPos[1] + 0.6 > blockY &&
          pPos[1] - 0.6 < blockY + 1 &&
          pPos[2] + 0.4 > pz &&
          pPos[2] - 0.4 < pz + 1;

        if (intersects) {
          return; // Blocked!
        }

        if (addCube(px, py, pz)) {
          gameAudio.playGlobal('place');
        }
      }
    };

    window.addEventListener('mousedown', onMouseDown);
    return () => window.removeEventListener('mousedown', onMouseDown);
  }, [damageBlock, addCube]);

  return null; // purely logical — renders nothing
};

import { useFrame } from '@react-three/fiber';
import { useStore } from '../stores/useStore';
import { useRef, useMemo } from 'react';
import * as THREE from 'three';

const MAX_BULLETS = 100;
const BULLET_GEO = new THREE.SphereGeometry(0.2, 8, 8); // Made larger (0.2 radius)
const BULLET_MAT = new THREE.MeshStandardMaterial({
  color: '#ffaa00',
  emissive: '#ff0000',
  emissiveIntensity: 2,
  toneMapped: false,
});
const _dummy = new THREE.Object3D();

export const Bullets = () => {
  const meshRef = useRef();

  useFrame((state, delta) => {
    if (!meshRef.current) return;
    const projectiles = useStore.getState().visualProjectiles || [];

    // Hide all instances by default (move far away)
    for (let i = 0; i < MAX_BULLETS; i++) {
      _dummy.position.set(0, -1000 - i, 0);
      _dummy.updateMatrix();
      meshRef.current.setMatrixAt(i, _dummy.matrix);
    }

    const now = performance.now();
    let index = 0;

    for (const p of projectiles) {
      if (index >= MAX_BULLETS) break;

      // Linear Math: position += velocity * (timeAlive_in_seconds)
      const ageSec = (now - p.createdAt) / 1000;

      // Destory if alive longer than 5 seconds without impact
      if (ageSec > 5) {
        useStore.getState().destroyVisualProjectile(p.id, null);
        continue;
      }

      const curX = p.pos[0] + p.vel[0] * ageSec;
      const curY = p.pos[1] + p.vel[1] * ageSec; // Could add -9.8 * ageSec^2 / 2 for gravity arc if we wanted
      const curZ = p.pos[2] + p.vel[2] * ageSec;

      _dummy.position.set(curX, curY, curZ);
      _dummy.updateMatrix();
      meshRef.current.setMatrixAt(index, _dummy.matrix);
      index++;
    }

    meshRef.current.instanceMatrix.needsUpdate = true;
  });

  return (
    <group>
      <instancedMesh
        ref={meshRef}
        args={[BULLET_GEO, BULLET_MAT, MAX_BULLETS]}
        frustumCulled={false}
      />
    </group>
  );
};

/**
 * Chunk.jsx — Visual rendering via greedy-meshed BufferGeometry.
 *
 * PERFORMANCE ARCHITECTURE:
 *
 *  FAST PATH ONLY:
 *    The main thread NEVER computes greedy meshes anymore.
 *    If a chunk is modified (e.g., block placed/broken), the Zustand store
 *    retains the old mesh arrays and fires a background worker task.
 *    This component simply renders whatever `meshArrays` it is given, keeping
 *    the main thread at a perfect 60fps even during massive explosions.
 *
 * GEOMETRY DISPOSAL:
 *    Three.js BufferGeometry objects are GPU resources (VAO + VBO).
 *    We dispose them when meshArrays change and on component unmount.
 *
 * INTERACTION:
 *    This component has NO onClick / onPointerMove handlers.
 *    Block picking is handled by BlockInteraction.jsx using the Amanatides-Woo
 *    DDA algorithm against the raw CPU block grid — not these mesh triangles.
 */

import {
  useRef,
  useState,
  useLayoutEffect,
  useEffect,
  useMemo,
  memo,
} from 'react';
import * as THREE from 'three';
import { useStore } from '../stores/useStore';
import {
  BlockRegistry,
  BlockById,
  BlockKeyById,
} from '../registry/BlockRegistry';
import { getTextureId, getIsHidden, CHUNK_Y_MIN } from '../utils/chunkData';

import { getTextureAtlas } from '../utils/TextureAtlas';
import { createChunkMaterial } from '../materials/ChunkMaterial';
import { ChunkFlora } from './ChunkFlora';
import { occlusionScene } from '../utils/OcclusionScene';

export const materialCache = new Map();

let solidMaterial = null;
let transparentMaterial = null;

const getSolidMaterial = () => {
  if (!solidMaterial) {
    solidMaterial = createChunkMaterial(getTextureAtlas(), false);
    materialCache.set('solid', solidMaterial);
  }
  return solidMaterial;
};

const getTransparentMaterial = () => {
  if (!transparentMaterial) {
    transparentMaterial = createChunkMaterial(getTextureAtlas(), true);
    materialCache.set('transparent', transparentMaterial);
  }
  return transparentMaterial;
};

// We expose them in materialCache so Cubes.jsx can still animate uTime
materialCache.set('solid', getSolidMaterial());
materialCache.set('transparent', getTransparentMaterial());

// ── Build BufferGeometry objects from pre-computed typed arrays ──────────────────
// This is the FAST PATH — pure Three.js object creation, no geometry computation.

function buildGeometriesFromArrays(meshArrays, cx, cz) {
  const result = {};

  for (const [name, data] of Object.entries(meshArrays)) {
    if (name === '__meta' || name === '__flora') continue;
    if (name === '__physics' || name === '_physics') {
      result[name] = { isRawArray: true, data };
      continue;
    }

    const { pos, norm, color, uv, idx } = data;
    if (!pos || pos.length === 0) continue;

    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    g.setAttribute('normal', new THREE.BufferAttribute(norm, 3, false));
    if (color && color.length > 0) {
      g.setAttribute('packedData', new THREE.BufferAttribute(color, 1));
    }
    if (uv && uv.length > 0) {
      g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    }
    g.setIndex(new THREE.Uint32BufferAttribute(idx, 1));

    // Debug logging for GL_INVALID_OPERATION
    let maxIdx = 0;
    for (let i = 0; i < idx.length; i++) {
      if (idx[i] > maxIdx) maxIdx = idx[i];
    }
    if (maxIdx >= pos.length / 3) {
      console.error(
        `Chunk geometry error in ${name}! maxIdx: ${maxIdx}, pos.count: ${pos.length / 3}`
      );
    }

    const meta = meshArrays['__meta'];
    if (meta && meta.boundingBox && meta.boundingBox.min[0] !== Infinity) {
      const { min, max } = meta.boundingBox;
      g.boundingBox = new THREE.Box3(
        new THREE.Vector3(min[0], min[1], min[2]),
        new THREE.Vector3(max[0] + 1, max[1] + 1, max[2] + 1) // +1 to cover the full block width
      );
      g.boundingSphere = new THREE.Sphere();
      g.boundingBox.getBoundingSphere(g.boundingSphere);
    } else {
      g.computeBoundingSphere(); // Fallback if no meta
    }

    result[name] = { geometry: g };
  }
  return result;
}

// ── Chunk component ───────────────────────────────────────────────────────────

export const Chunk = memo(({ chunkKey, shadowsEnabled }) => {
  const chunkData = useStore((state) => state.chunks[chunkKey]);
  const clearVisualMeshArrays = useStore(
    (state) => state.clearVisualMeshArrays
  );
  const [cx, cz] = chunkKey.split(',').map(Number);

  // Double‑buffered geometry handling – safe disposal without race conditions
  const [geometries, setGeometries] = useState({});
  // Holds the previous geometry set for disposal after the layout commit
  const prevGeosRef = useRef({});

  useLayoutEffect(() => {
    // Build new BufferGeometries from the latest meshArrays (if any)
    if (
      !chunkData ||
      !chunkData.meshArrays ||
      Object.keys(chunkData.meshArrays).length === 0
    ) {
      setGeometries({});
      return;
    }

    const newGeos = buildGeometriesFromArrays(chunkData.meshArrays, cx, cz);

    // Create shadow meshes for OcclusionScene
    const shadowMeshes = [];
    if (newGeos['solid']) {
      const sm = new THREE.Mesh(newGeos['solid'].geometry);
      // Important: Position isn't needed here because chunk geometries are built with absolute world coordinates
      occlusionScene.add(sm);
      shadowMeshes.push(sm);
    }
    if (newGeos['transparent']) {
      const tm = new THREE.Mesh(newGeos['transparent'].geometry);
      occlusionScene.add(tm);
      shadowMeshes.push(tm);
    }

    // Track the currently active geometries for this render cycle
    setGeometries(newGeos);
    prevGeosRef.current = newGeos;

    // Cleanup function runs when this chunk updates OR unmounts.
    // It must dispose the geometries CREATED IN THIS RUN (newGeos),
    // because React will have already rendered the next updated state.
    return () => {
      // Remove shadow meshes from occlusion scene and DISPOSE the auto-generated material
      shadowMeshes.forEach((sm) => {
        occlusionScene.remove(sm);
        if (sm.material) sm.material.dispose();
      });

      for (const [name, obj] of Object.entries(newGeos)) {
        if (!obj) continue;

        if (obj.isRawArray) continue;

        const g = obj.geometry;
        if (!g || !g.attributes) continue;

        g.dispose();
      }
    };
  }, [chunkData?.meshArrays, chunkKey, clearVisualMeshArrays]);

  // Ensure any remaining geometries are disposed when the component finally unmounts
  useEffect(
    () => () => {
      for (const [name, obj] of Object.entries(prevGeosRef.current)) {
        if (!obj) continue;

        if (obj.isRawArray) continue;

        const g = obj.geometry || obj;

        // Dispose FIRST, so Three.js can iterate attributes and delete WebGL buffers!
        g.dispose();

        // Nullify to prevent React Strict Mode from trying to recycle detached buffers again
        if (g.attributes) {
          g.attributes.position = null;
          g.attributes.normal = null;
          g.attributes.color = null;
          g.attributes.uv = null;
          g.attributes.packedData = null;
        }
        g.index = null;
      }
    },
    []
  );

  if (Object.keys(geometries).length === 0) {
    return null;
  }

  const meshGroup = (
    <group name={`chunk-visuals-${chunkKey}`}>
      {geometries['solid'] && (
        <mesh
          key="solid"
          geometry={geometries['solid'].geometry}
          material={getSolidMaterial()}
          castShadow={shadowsEnabled}
          receiveShadow={shadowsEnabled}
          onBeforeRender={() => {
            if (window.__DEBUG_STATS__) window.__DEBUG_STATS__.chunksRendered++;
          }}
        />
      )}
      {geometries['transparent'] && (
        <mesh
          key="transparent"
          geometry={geometries['transparent'].geometry}
          material={getTransparentMaterial()}
          castShadow={shadowsEnabled}
          receiveShadow={shadowsEnabled}
          onBeforeRender={() => {
            if (window.__DEBUG_STATS__) window.__DEBUG_STATS__.chunksRendered++;
          }}
        />
      )}
      {chunkData?.meshArrays?.__flora &&
        chunkData.meshArrays.__flora.packed?.length > 0 &&
        (() => {
          if (!window.__CHUNK_FLORA_RENDER_ATTEMPT__)
            window.__CHUNK_FLORA_RENDER_ATTEMPT__ = true;
          return (
            <ChunkFlora
              key="flora"
              floraData={chunkData.meshArrays.__flora}
              shadowsEnabled={shadowsEnabled}
              meta={chunkData.meshArrays.__meta}
            />
          );
        })()}
    </group>
  );

  return <group name={`chunk-${chunkKey}`}>{meshGroup}</group>;
});

