import { useFrame, useThree } from '@react-three/fiber';
import { useEffect, useRef } from 'react';

export const DebugTracker = () => {
  const { gl, scene, camera } = useThree();

  const frameTimes = useRef([]);
  const lastTime = useRef(performance.now());
  const cpuStart = useRef(0);

  const extRef = useRef(null);
  const queryRef = useRef(null);
  const isQueryRunning = useRef(false);

  useEffect(() => {
    // Attempt to get the WebGL2 disjoint timer extension
    const glContext = gl.getContext();
    extRef.current = glContext.getExtension('EXT_disjoint_timer_query_webgl2');
  }, [gl]);

  // Priority -1 runs first in the frame loop
  useFrame(() => {
    cpuStart.current = performance.now();

    if (window.__DEBUG_STATS__) {
      // Reset our custom WebGL tracker counters to 0 at the start of the frame.
      window.__DEBUG_STATS__.drawCalls = 0;
      window.__DEBUG_STATS__.triangles = 0;
      window.__DEBUG_STATS__.vertices = 0;
      window.__DEBUG_STATS__.textureBinds = 0;

      window.__DEBUG_STATS__.chunksRendered = 0;
      window.__DEBUG_STATS__.entitiesRendered = 0;
      window.__DEBUG_STATS__.totalEntities = 0; // Will be summed up by SwarmManagers
    }
  }, -1);

  // Priority 1 runs last, and intercepts the default R3F render call
  useFrame(() => {
    if (!window.__DEBUG_STATS__) return;

    const stats = window.__DEBUG_STATS__;
    const glContext = gl.getContext();
    const ext = extRef.current;

    // --- GPU Render Tracking ---
    if (ext) {
      if (!queryRef.current) queryRef.current = glContext.createQuery();

      // If previous query is done, read it
      if (isQueryRunning.current) {
        const available = glContext.getQueryParameter(
          queryRef.current,
          glContext.QUERY_RESULT_AVAILABLE
        );
        const disjoint = glContext.getParameter(ext.GPU_DISJOINT_EXT);

        if (available && !disjoint) {
          const timeElapsed = glContext.getQueryParameter(
            queryRef.current,
            glContext.QUERY_RESULT
          );
          stats.gpuTime = timeElapsed / 1000000; // Convert nanoseconds to milliseconds
          isQueryRunning.current = false;
        }
      }

      // Start new query (or fallback render)
      if (!isQueryRunning.current) {
        glContext.beginQuery(ext.TIME_ELAPSED_EXT, queryRef.current);
        gl.render(scene, camera);
        glContext.endQuery(ext.TIME_ELAPSED_EXT);
        isQueryRunning.current = true;
      } else {
        // Query still pending – render without starting a new query
        gl.render(scene, camera);
      }
    } else {
      // Fallback: No WebGL2 Timer Support
      gl.render(scene, camera);
    }

    // --- WebGL Metrics ---
    // Extract stats natively from Three.js instead of double-hooking the context
    stats.drawCalls = gl.info.render.calls;
    stats.triangles = gl.info.render.triangles;
    stats.vertices = gl.info.render.points;
    stats.textureBinds = gl.info.memory.textures;
    stats.geometries = gl.info.memory.geometries;

    // --- CPU Time Tracking ---
    const now = performance.now();
    const cpuTime = now - cpuStart.current;

    frameTimes.current.push(cpuTime);
    if (frameTimes.current.length > 30) frameTimes.current.shift();

    // Calculate rolling average
    let sum = 0;
    for (let i = 0; i < frameTimes.current.length; i++) {
      sum += frameTimes.current[i];
    }
    const avgCpuTime = sum / frameTimes.current.length;

    // The total time elapsed between frames (including VSync/GPU wait) for FPS calc
    const frameDelta = now - lastTime.current;
    lastTime.current = now;

    stats.cpuTime = avgCpuTime;

    // FPS is 1000ms / actual frame delta (not cpu delta)
    if (frameDelta > 0) {
      stats.fps = Math.round(1000 / frameDelta);
    }
  }, 1);

  return null;
};

import { useFrame, useThree } from '@react-three/fiber';
import { useStore } from '../stores/useStore';
import { useRef, useEffect, useMemo } from 'react';
import { playerPosition } from '../globals';
import { BlockRegistry } from '../registry/BlockRegistry';
import * as THREE from 'three';
import {
  InstancedRigidBodies,
  CuboidCollider,
  useRapier,
} from '@react-three/rapier';
import { useNetworkStore } from '../stores/useNetworkStore';

const MAX_DROPS = 256; // Optimized pool size for performance
const ITEM_GEO = new THREE.BoxGeometry(1, 1, 1);
const ITEM_MAT = new THREE.MeshLambertMaterial({ color: '#ffffff' }); // Color gets overridden by instanceColor
const _dummy = new THREE.Object3D();
const _color = new THREE.Color();

export const DroppedItems = () => {
  const droppedItems = useStore((state) => state.droppedItems);
  const { rapier, world } = useRapier();

  const physicsRef = useRef();
  const meshRef = useRef();

  const activeKeys = useRef(new Map()); // Map<itemKey, poolIndex>
  const freeIndices = useRef(
    Array.from({ length: MAX_DROPS }).map((_, i) => i)
  );
  const tweening = useRef(new Map()); // key -> { startTime, startPos }

  // Initialize pool geometry off-screen
  const instances = useMemo(
    () =>
      Array.from({ length: MAX_DROPS }).map((_, i) => ({
        key: i,
        position: [0, -100 - i * 2, 0],
        rotation: [0, 0, 0],
      })),
    []
  );

  useEffect(() => {
    // 1. Free despawned/collected items
    const currentKeys = new Set(droppedItems.map((d) => d.key));
    for (const [key, index] of activeKeys.current.entries()) {
      if (!currentKeys.has(key)) {
        activeKeys.current.delete(key);
        tweening.current.delete(key);
        freeIndices.current.push(index);

        // Bury dead physics body
        const rb =
          typeof physicsRef.current?.at === 'function'
            ? physicsRef.current.at(index)
            : physicsRef.current?.[index];
        if (rb) {
          rb.setTranslation({ x: 0, y: -100 - index * 2, z: 0 }, true);
        }

        // Hide visual mesh
        _dummy.position.set(0, -100 - index * 2, 0);
        _dummy.updateMatrix();
        if (meshRef.current) {
          meshRef.current.setMatrixAt(index, _dummy.matrix);
          meshRef.current.instanceMatrix.needsUpdate = true;
        }
      }
    }

    // 2. Spawn new items
    droppedItems.forEach((item) => {
      if (!activeKeys.current.has(item.key)) {
        const index = freeIndices.current.shift();
        if (index === undefined) return; // Pool full!

        activeKeys.current.set(item.key, index);

        const rb =
          typeof physicsRef.current?.at === 'function'
            ? physicsRef.current.at(index)
            : physicsRef.current?.[index];
        if (rb) {
          const rayOrigin = new THREE.Vector3(
            item.pos[0],
            item.pos[1],
            item.pos[2]
          );
          const rayDir = new THREE.Vector3(0, -1, 0);
          const hit = world.castRay(
            new rapier.Ray(rayOrigin, rayDir),
            100,
            false
          );

          if (hit) {
            rb.setTranslation(
              {
                x: item.pos[0],
                y: item.pos[1] - hit.toi + 0.25,
                z: item.pos[2],
              },
              true
            );
          } else {
            rb.setTranslation(
              { x: item.pos[0], y: item.pos[1], z: item.pos[2] },
              true
            );
          }
        }
      }
    });
  }, [droppedItems, rapier, world]);

  const rejectCooldowns = useRef(new Map());

  useEffect(() => {
    const onReject = (e) => {
      tweening.current.delete(e.detail);
      rejectCooldowns.current.set(e.detail, performance.now() + 2000); // 2 second cooldown before trying to loot again
    };
    window.addEventListener('LOOT_REJECTED', onReject);
    return () => window.removeEventListener('LOOT_REJECTED', onReject);
  }, []);

  useFrame(({ clock, camera }) => {
    if (!physicsRef.current || !meshRef.current) return;
    const time = clock.elapsedTime;
    const state = useStore.getState();
    const netState = useNetworkStore.getState();
    const currentItems = state.droppedItems || [];

    let needsUpdate = false;

    for (const item of currentItems) {
      const idx = activeKeys.current.get(item.key);
      if (idx === undefined) continue;

      const rb =
        typeof physicsRef.current?.at === 'function'
          ? physicsRef.current.at(idx)
          : physicsRef.current?.[idx];
      if (!rb) continue;

      const trans = rb.translation();

      let renderPos = { x: trans.x, y: trans.y, z: trans.z };

      // Auto-collect logic (magnet radius = 3 blocks -> distSq < 9)
      const dx = playerPosition.x - trans.x;
      const dy = playerPosition.y - trans.y;
      const dz = playerPosition.z - trans.z;
      const distSq = dx * dx + dy * dy + dz * dz;

      const cooldown = rejectCooldowns.current.get(item.key) || 0;
      const pickupCooldown = item.pickupCooldown || 0;

      if (
        distSq < 9 &&
        !tweening.current.has(item.key) &&
        performance.now() > cooldown &&
        Date.now() > pickupCooldown
      ) {
        tweening.current.set(item.key, {
          startTime: performance.now(),
          startPos: new THREE.Vector3(trans.x, trans.y, trans.z),
        });
        // Fire LOOT_INTENT
        const intent = { type: 'LOOT_INTENT', dropId: item.key };
        netState.broadcastEvent(intent);
        if (netState.isHost) {
          netState.handleNetworkData(intent, {
            metadata: { playerId: netState.playerId },
          });
        }
      }

      // Client-Side Tweening
      if (tweening.current.has(item.key)) {
        const tweenData = tweening.current.get(item.key);
        const elapsed = performance.now() - tweenData.startTime;
        if (elapsed < 150) {
          const alpha = elapsed / 150;
          // Lerp from startPos to Camera Position
          const camPos = camera.position;
          renderPos.x = THREE.MathUtils.lerp(
            tweenData.startPos.x,
            camPos.x,
            alpha
          );
          renderPos.y = THREE.MathUtils.lerp(
            tweenData.startPos.y,
            camPos.y - 0.5,
            alpha
          ); // Pull slightly below eye level
          renderPos.z = THREE.MathUtils.lerp(
            tweenData.startPos.z,
            camPos.z,
            alpha
          );
        } else {
          // Wait for DESPAWN_LOOT or LOOT_REJECTED (which will clear it)
          const camPos = camera.position;
          renderPos.x = camPos.x;
          renderPos.y = camPos.y - 0.5;
          renderPos.z = camPos.z;
        }
      }

      // Memory Leak Fix: Despawn items that fall into the void (though static shouldn't fall, this catches bugs)
      if (renderPos.y < -65) {
        state.despawnLoot(item.key);
        continue;
      }

      // Visually float and spin the inner mesh while the physics body rests on the floor
      _dummy.position.set(
        renderPos.x,
        renderPos.y + Math.sin(time * 3 + idx) * 0.1,
        renderPos.z
      );
      _dummy.rotation.set(0, time * 2 + idx, 0);
      _dummy.scale.set(0.25, 0.25, 0.25);
      _dummy.updateMatrix();
      meshRef.current.setMatrixAt(idx, _dummy.matrix);

      // Update Instance Color
      const reg = BlockRegistry[item.texture];
      _color.set(reg?.color ?? '#ffffff');
      meshRef.current.setColorAt(idx, _color);

      needsUpdate = true;
    }

    if (needsUpdate) {
      meshRef.current.instanceMatrix.needsUpdate = true;
      if (meshRef.current.instanceColor) {
        meshRef.current.instanceColor.needsUpdate = true;
      }
    }
  });

  return (
    <group>
      <InstancedRigidBodies
        ref={physicsRef}
        instances={instances}
        type="fixed"
        colliders="cuboid"
        sensor={true}
        collisionGroups={0x00080008}
      >
        {/* We use a tiny collider box, visually the mesh is scaled to 0.25 */}
        <instancedMesh
          ref={meshRef}
          args={[ITEM_GEO, ITEM_MAT, MAX_DROPS]}
          castShadow={false}
          frustumCulled={false}
        >
          {/* Provide an initial color buffer so Three.js creates the attribute array */}
          <instancedBufferAttribute
            attach="instanceColor"
            args={[new Float32Array(MAX_DROPS * 3).fill(1), 3]}
          />
        </instancedMesh>
      </InstancedRigidBodies>
    </group>
  );
};

import { RigidBody } from '@react-three/rapier';
import { useStore } from '../stores/useStore';
import { useRef, useEffect, useState } from 'react';
import { useFrame } from '@react-three/fiber';
import { playerPosition } from '../globals';
import * as THREE from 'three';
import { MaterialCache } from '../utils/MaterialCache';

import { GlobalRegistry } from '../registry/Registry';

export const DynamicCube = ({ block }) => {
  const bakeCube = useStore((state) => state.bakeCube);

  const addCube = useStore((state) => state.addCube);
  const setHoverTarget = useStore((state) => state.setHoverTarget);
  const damageBlock = useStore((state) => state.damageBlock);
  const removeDebris = useStore((state) => state.removeDebris);
  const ref = useRef();
  const meshRef = useRef();

  useEffect(() => {
    if (ref.current) {
      ref.current.wakeUp();
      ref.current.applyImpulse(
        {
          x: (Math.random() - 0.5) * 0.5,
          y: -0.01,
          z: (Math.random() - 0.5) * 0.5,
        },
        true
      );
    }
  }, []);

  const hasRemoved = useRef(false);
  useFrame(() => {
    if (!block.isDebris || hasRemoved.current) return; // Completely bail out if not debris (optimization)

    const age = Date.now() - block.createdAt;
    if (age > 8000) {
      // Shrink for the last 2 seconds
      const shrinkFactor = Math.max(0, 1 - (age - 8000) / 2000);
      if (meshRef.current) {
        meshRef.current.scale.setScalar(shrinkFactor);
      }
      if (shrinkFactor === 0) {
        hasRemoved.current = true;
        removeDebris(block.key);
      }
    }
  });

  return (
    <RigidBody
      ref={ref}
      type="dynamic"
      position={[block.pos[0] + 0.5, block.pos[1] + 0.5, block.pos[2] + 0.5]}
      colliders="cuboid"
      onSleep={() => {
        if (ref.current && !block.isDebris) {
          const trans = ref.current.translation();
          // Defer state update to next tick to avoid unmounting the RigidBody during Rapier physics step
          setTimeout(() => {
            bakeCube(block.key, [trans.x, trans.y, trans.z]);
          }, 0);
        }
      }}
    >
      <mesh
        ref={meshRef}
        castShadow
        receiveShadow
        material={MaterialCache.getStandard(
          GlobalRegistry[block.texture]?.color || '#ffffff',
          GlobalRegistry[block.texture]?.isTransparent || false,
          GlobalRegistry[block.texture]?.isTransparent ? 0.6 : 1
        )}
      >
        <boxGeometry />
      </mesh>
    </RigidBody>
  );
};

