import { useRef, useEffect } from 'react';
import { RigidBody, CuboidCollider } from '@react-three/rapier';
import { useStore } from '../stores/useStore';
import { MaterialCache } from '../utils/MaterialCache';
import * as THREE from 'three';
import { gameAudio } from '../audio/GameAudio';

const getColor = (texture) => {
  switch (texture) {
    case 'dirt':
      return '#8B4513';
    case 'grass':
      return '#4CAF50';
    case 'glass':
      return '#add8e6';
    case 'wood':
      return '#DEB887';
    case 'log':
      return '#654321';
    case 'leaves':
      return '#228B22';
    case 'stone':
      return '#888888';
    case 'tnt':
      return '#ff3333';
    default:
      return '#ffffff';
  }
};

export const FallingStructure = ({ structure }) => {
  const ref = useRef();
  const shatterStructure = useStore((state) => state.shatterStructure);
  const activeTexture = useStore((state) => state.texture);

  // Calculate center of mass roughly (the average position)
  const center = new THREE.Vector3(0, 0, 0);
  structure.blocks.forEach((b) =>
    center.add(new THREE.Vector3(b.x + 0.5, b.y + 0.5, b.z + 0.5))
  );
  if (structure.blocks.length > 0) {
    center.divideScalar(structure.blocks.length);
  }

  useEffect(() => {
    if (ref.current) {
      ref.current.wakeUp();
      // Apply a dramatic rotational impulse to force it to tip over sideways!
      ref.current.applyTorqueImpulse(
        {
          x: (Math.random() - 0.5) * 5,
          y: 0,
          z: (Math.random() - 0.5) * 5,
        },
        true
      );
    }

    // FAILSAFE: If the structure falls into the void and never collides,
    // force shatter it after 15 seconds to prevent an infinite physics leak!
    const timeout = setTimeout(() => triggerShatter(), 15000);
    return () => clearTimeout(timeout);
  }, []);

  const handleCollision = (e) => {
    if (!ref.current) return;

    // Shatter if hitting ground, terrain, or experiencing significant force
    const hitName = e.target.rigidBodyObject?.name;
    if (
      hitName === 'ground' ||
      hitName === 'terrain' ||
      e.totalForceMagnitude > 20
    ) {
      triggerShatter();
    }
  };

  const hasShattered = useRef(false);

  const triggerShatter = () => {
    if (!ref.current || hasShattered.current) return;
    hasShattered.current = true;
    const translation = ref.current.translation();
    const rotation = ref.current.rotation();
    const quat = new THREE.Quaternion(
      rotation.x,
      rotation.y,
      rotation.z,
      rotation.w
    );
    const groupPos = new THREE.Vector3(
      translation.x,
      translation.y,
      translation.z
    );

    // Calculate exact world position of every sub-block
    const debrisBlocks = structure.blocks.map((block) => {
      // block.x/y/z is absolute integer. True center is +0.5. We need its relative pos to the center
      const localPos = new THREE.Vector3(
        block.x + 0.5,
        block.y + 0.5,
        block.z + 0.5
      ).sub(center);

      // Apply tumbling rotation
      localPos.applyQuaternion(quat);

      // Add back the global position of the tumbling rigid body
      const worldPos = localPos.add(groupPos);

      return {
        ...block,
        pos: [worldPos.x, worldPos.y, worldPos.z],
        isDebris: true,
        createdAt: Date.now(),
      };
    });
    // Defer state update to next tick to avoid unmounting the RigidBody while Rapier is inside a physics step
    setTimeout(() => {
      shatterStructure(structure.id, debrisBlocks);
    }, 0);
  };

  return (
    <RigidBody
      ref={ref}
      type="dynamic"
      position={[center.x, center.y, center.z]}
      onCollisionEnter={handleCollision}
      mass={structure.blocks.length * 0.5}
    >
      <group>
        {structure.blocks.map((block) => {
          // Relative position for colliders and meshes
          const rx = block.x + 0.5 - center.x;
          const ry = block.y + 0.5 - center.y;
          const rz = block.z + 0.5 - center.z;

          return (
            <group
              key={`${block.x},${block.y},${block.z}`}
              position={[rx, ry, rz]}
            >
              <CuboidCollider args={[0.45, 0.45, 0.45]} />
              <mesh
                castShadow
                receiveShadow
                material={MaterialCache.getStandard(
                  getColor(block.texture),
                  block.texture === 'glass',
                  block.texture === 'glass' ? 0.6 : 1
                )}
                onClick={(e) => {
                  e.stopPropagation();
                  if (e.distance > 8) return;
                  if (
                    activeTexture === 'pickaxe' ||
                    activeTexture === 'sword' ||
                    activeTexture === 'gun'
                  ) {
                    gameAudio.playGlobal('break');
                    triggerShatter();
                  }
                }}
              >
                <boxGeometry args={[1, 1, 1]} />
              </mesh>
            </group>
          );
        })}
      </group>
    </RigidBody>
  );
};

import { memo, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../stores/useStore';
import { useShallow } from 'zustand/react/shallow';
import * as THREE from 'three';

// ── Shared geometries (module-level, allocated once) ──────────────────────────
const STICK_GEO = new THREE.CylinderGeometry(0.045, 0.055, 0.6, 6);
const FLAME_GEO = new THREE.CylinderGeometry(0.0, 0.075, 0.14, 8); // cone tip
const EMBER_GEO = new THREE.SphereGeometry(0.06, 8, 6);

const STICK_MAT = new THREE.MeshLambertMaterial({ color: '#7a5230' }); // brown wood
const FLAME_MAT = new THREE.MeshBasicMaterial({ color: '#ff6600' }); // orange cone
const EMBER_MAT = new THREE.MeshBasicMaterial({ color: '#ffee22' }); // bright yellow tip

const MAX_FLARES = 5000;

export const Flares = () => {
  const flares = useStore(useShallow((state) => state.placedFlares));

  const stickRef = useRef();
  const flameRef = useRef();
  const emberRef = useRef();

  const dummyStick = useMemo(() => new THREE.Object3D(), []);
  const dummyFlame = useMemo(() => new THREE.Object3D(), []);
  const dummyEmber = useMemo(() => new THREE.Object3D(), []);

  useEffect(() => {
    if (!stickRef.current || !flameRef.current || !emberRef.current) return;

    for (let i = 0; i < flares.length; i++) {
      const f = flares[i];
      const [nx, ny, nz] = f.normal;

      let rx = 0,
        ry = 0,
        rz = 0;
      if (ny > 0.5) {
        rx = 0;
      } else if (ny < -0.5) {
        rx = Math.PI;
      } else if (nx > 0.5) {
        rz = -Math.PI * 0.35;
      } else if (nx < -0.5) {
        rz = Math.PI * 0.35;
      } else if (nz > 0.5) {
        rx = Math.PI * 0.35;
      } else {
        rx = -Math.PI * 0.35;
      }

      const mx = f.pos[0] + nx * 0.06;
      const my = f.pos[1] + ny * 0.06;
      const mz = f.pos[2] + nz * 0.06;

      // Base rotation
      const euler = new THREE.Euler(rx, ry, rz);
      const quat = new THREE.Quaternion().setFromEuler(euler);

      // Stick Dummy
      dummyStick.position.set(mx, my, mz);
      dummyStick.quaternion.copy(quat);
      dummyStick.updateMatrix();
      stickRef.current.setMatrixAt(i, dummyStick.matrix);

      // Flame Dummy (offset Y=0.37 local)
      const fPos = new THREE.Vector3(0, 0.37, 0)
        .applyQuaternion(quat)
        .add(dummyStick.position);
      dummyFlame.position.copy(fPos);
      dummyFlame.quaternion.copy(quat);
      dummyFlame.updateMatrix();
      flameRef.current.setMatrixAt(i, dummyFlame.matrix);

      // Ember Dummy (offset Y=0.46 local)
      const ePos = new THREE.Vector3(0, 0.46, 0)
        .applyQuaternion(quat)
        .add(dummyStick.position);
      dummyEmber.position.copy(ePos);
      dummyEmber.quaternion.copy(quat);
      dummyEmber.updateMatrix();
      emberRef.current.setMatrixAt(i, dummyEmber.matrix);
    }

    stickRef.current.count = flares.length;
    flameRef.current.count = flares.length;
    emberRef.current.count = flares.length;

    stickRef.current.instanceMatrix.needsUpdate = true;
    flameRef.current.instanceMatrix.needsUpdate = true;
    emberRef.current.instanceMatrix.needsUpdate = true;
  }, [flares, dummyStick, dummyFlame, dummyEmber]);

  return (
    <group>
      <instancedMesh
        ref={stickRef}
        args={[STICK_GEO, STICK_MAT, MAX_FLARES]}
        frustumCulled={false}
      />
      <instancedMesh
        ref={flameRef}
        args={[FLAME_GEO, FLAME_MAT, MAX_FLARES]}
        frustumCulled={false}
      />
      <instancedMesh
        ref={emberRef}
        args={[EMBER_GEO, EMBER_MAT, MAX_FLARES]}
        frustumCulled={false}
      />
    </group>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { useFrame } from '@react-three/fiber';
import { useRapier, RigidBody, BallCollider } from '@react-three/rapier';
import * as THREE from 'three';
import { useStore } from '../stores/useStore';
import { useNetworkStore } from '../stores/useNetworkStore';
import { GlobalRegistry } from '../registry/Registry';

// Generates unique IDs for projectiles
let projIdCounter = 0;

export function HostCombat() {
  const { world, rapier } = useRapier();
  const networkStore = useNetworkStore.getState();
  const isHost = useNetworkStore((state) => state.isHost);
  const [projectiles, setProjectiles] = useState([]);

  // Projectile limits and tracking
  const maxProjectiles = 100;

  useFrame(() => {
    if (!isHost) return;
    // 1. Process pending attacks
    const pendingAttacks = networkStore.popPendingAttacks();

    for (const attack of pendingAttacks) {
      const { senderId, weaponId, dir, origin, timestamp } = attack;

      const weaponDef = GlobalRegistry[weaponId];
      const combatStats = weaponDef?.combat;
      if (!combatStats) continue;

      // Validate Cooldown
      const lastTime = (networkStore.lastAttackTimestamps || {})[senderId] || 0;
      if (timestamp - lastTime < combatStats.cooldownMs * 0.9) {
        // Too fast, ignore (0.9 to allow slight network variance)
        continue;
      }
      useNetworkStore.setState((prev) => ({
        lastAttackTimestamps: {
          ...prev.lastAttackTimestamps,
          [senderId]: timestamp,
        },
      }));

      const originVec = new THREE.Vector3(origin[0], origin[1], origin[2]);
      const dirVec = new THREE.Vector3(dir[0], dir[1], dir[2]);
      if (dirVec.lengthSq() < 0.0001) dirVec.set(0, 0, 1);
      else dirVec.normalize();

      // Projectile Resolution
      if (combatStats.type === 'projectile') {
        const projId = `proj_${++projIdCounter}`;

        // Advance the origin slightly so it doesn't collide with the player shooting it
        const startPos = originVec.clone().addScaledVector(dirVec, 1.0);
        const velocity = dirVec.clone().multiplyScalar(combatStats.speed || 40);

        const newProj = {
          id: projId,
          position: [startPos.x, startPos.y, startPos.z],
          velocity: [velocity.x, velocity.y, velocity.z],
          damage: combatStats.damage,
          sourceId: senderId,
          createdAt: performance.now(),
        };

        setProjectiles((prev) => {
          const next = [...prev, newProj];
          if (next.length > maxProjectiles) next.shift();
          return next;
        });

        // Broadcast to network for clients to render deterministic tracers
        networkStore.broadcastEvent({
          type: 'SPAWN_PROJECTILE',
          id: projId,
          origin: [startPos.x, startPos.y, startPos.z],
          velocity: [velocity.x, velocity.y, velocity.z],
        });

        // Locally trigger visual spawn
        useStore.getState().spawnVisualProjectile({
          id: projId,
          origin: [startPos.x, startPos.y, startPos.z],
          velocity: [velocity.x, velocity.y, velocity.z],
        });
      } else if (combatStats.type === 'hitscan') {
        const startPos = originVec.clone().addScaledVector(dirVec, 0.5);
        const ray = new rapier.Ray(startPos, dirVec);

        // Host physics engine is authoritative!
        const hit = world.castRay(
          ray,
          combatStats.range || 5,
          false,
          0x00030003
        );

        let endPos = startPos
          .clone()
          .addScaledVector(dirVec, combatStats.range || 5);
        if (hit) endPos = startPos.clone().addScaledVector(dirVec, hit.toi);

        if (
          weaponId === 'sword' ||
          weaponId === 'pickaxe' ||
          combatStats.range <= 5
        ) {
          // MELEE WEAPONS: Thick sweeping hitbox
          // Ignore the thin raycast point and place a massive cleave right in front of the player.
          // This guarantees we hit tiny enemies like Muck Pigs even if the crosshair misses slightly.
          const reach = combatStats.range || 4;
          const centerPos = originVec
            .clone()
            .addScaledVector(dirVec, reach * 0.45);
          const sweepRadius = reach * 0.55;
          useStore
            .getState()
            .requestAreaDamage(
              [centerPos.x, centerPos.y, centerPos.z],
              sweepRadius,
              combatStats.damage,
              senderId
            );
        } else {
          // RANGED HITSCAN (Gauss Rifle)
          // Needs pinpoint accuracy at the raycast hit point
          const radius = combatStats.areaOfEffect || 1.0;
          useStore
            .getState()
            .requestAreaDamage(
              [endPos.x, endPos.y, endPos.z],
              radius,
              combatStats.damage,
              senderId
            );
        }
      }
    }

    // 2. Cleanup old physical projectiles to save memory
    const now = performance.now();
    setProjectiles((prev) => {
      const valid = prev.filter((p) => now - p.createdAt < 5000); // 5 sec max lifetime
      if (valid.length !== prev.length) return valid;
      return prev;
    });
  });

  // Render the physical rigidbodies
  if (!isHost) return null;

  return (
    <group>
      {projectiles.map((proj) => (
        <HostProjectile
          key={proj.id}
          proj={proj}
          onImpact={(impactPoint, hitUserData) => {
            // Impact resolved
            setProjectiles((prev) => prev.filter((p) => p.id !== proj.id));

            // Broadcast impact event
            networkStore.broadcastEvent({
              type: 'PROJECTILE_IMPACT',
              id: proj.id,
              point: impactPoint,
            });

            // Locally destroy visual
            useStore.getState().destroyVisualProjectile(proj.id, impactPoint);

            // INSTEAD OF USERDATA: Trigger a small localized explosion/cleave at impact
            useStore
              .getState()
              .requestAreaDamage(impactPoint, 1.5, proj.damage, proj.sourceId);
          }}
        />
      ))}
    </group>
  );
}

function HostProjectile({ proj, onImpact }) {
  const rbRef = useRef();

  // Only apply initial velocity once
  useEffect(() => {
    if (rbRef.current) {
      rbRef.current.setLinvel(
        { x: proj.velocity[0], y: proj.velocity[1], z: proj.velocity[2] },
        true
      );
    }
  }, [proj.velocity]);

  return (
    <RigidBody
      ref={rbRef}
      position={proj.position}
      type="dynamic"
      gravityScale={0.1} // Slight gravity for arrows/bullets
      ccd={true} // Continuous Collision Detection to prevent tunneling
      onIntersectionEnter={(payload) => {
        const hitPos = rbRef.current
          ? rbRef.current.translation()
          : proj.position;
        const userData = payload.colliderObject?.userData;
        // Defer to next tick to avoid Rapier unsafe aliasing crash when unmounting the RigidBody
        setTimeout(() => {
          onImpact([hitPos.x, hitPos.y, hitPos.z], userData);
        }, 0);
      }}
    >
      <BallCollider args={[0.2]} sensor />
    </RigidBody>
  );
}

import React, { useEffect, useMemo, useRef } from 'react';
import { useStore } from '../stores/useStore';
import { useKeyboard } from '../hooks/useKeyboard';
import { GlobalRegistry } from '../registry/Registry';

export const Hotbar = () => {
  const inventory = useStore((state) => state.inventory);
  const activeHotbarIndex = useStore((state) => state.activeHotbarIndex);
  const setActiveHotbarIndex = useStore((state) => state.setActiveHotbarIndex);
  const coins = useStore((state) => state.coins);
  const keys = useKeyboard();
  const isInventoryOpen = useStore((state) => state.isInventoryOpen);
  const isMenuOpen = useStore((state) => state.isMenuOpen);
  const isSettingsOpen = useStore((state) => state.isSettingsOpen);
  const isDead = useStore((state) => state.isDead);

  const hotbarItems = useMemo(() => {
    const items = inventory.slice(0, 9);
    while (items.length < 9) items.push(null);
    return items;
  }, [inventory]);

  // We will conditionally return null after all hooks

  useEffect(() => {
    if (useStore.getState().isInventoryOpen) return;

    // Keyboard 1-9
    if (keys.slot1) setActiveHotbarIndex(0);
    if (keys.slot2) setActiveHotbarIndex(1);
    if (keys.slot3) setActiveHotbarIndex(2);
    if (keys.slot4) setActiveHotbarIndex(3);
    if (keys.slot5) setActiveHotbarIndex(4);
    if (keys.slot6) setActiveHotbarIndex(5);
    if (keys.slot7) setActiveHotbarIndex(6);
    if (keys.slot8) setActiveHotbarIndex(7);
    if (keys.slot9) setActiveHotbarIndex(8);
  }, [keys, setActiveHotbarIndex]);

  const activeIdxRef = useRef(activeHotbarIndex);
  useEffect(() => {
    activeIdxRef.current = activeHotbarIndex;
  }, [activeHotbarIndex]);

  // Handle mouse wheel scrolling — registers once, reads latest index via ref
  // Handle mouse wheel scrolling and Q to drop
  useEffect(() => {
    const handleWheel = (e) => {
      if (document.pointerLockElement) {
        const cur = activeIdxRef.current;
        if (e.deltaY > 0) {
          setActiveHotbarIndex((cur + 1) % 9);
        } else if (e.deltaY < 0) {
          setActiveHotbarIndex((cur - 1 + 9) % 9);
        }
      }
    };

    const handleKeyDown = (e) => {
      if (document.pointerLockElement && e.code === 'KeyQ') {
        useStore
          .getState()
          .dropItemFromSlot('inventory', activeIdxRef.current, false);
      }
    };

    window.addEventListener('wheel', handleWheel);
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('wheel', handleWheel);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [setActiveHotbarIndex]); // no activeHotbarIndex dep — use ref instead

  const activeItem = hotbarItems[activeHotbarIndex];
  const activeReg = activeItem ? GlobalRegistry[activeItem.texture] : null;

  // Hide hotbar completely during menus and death screen
  if (isInventoryOpen || isMenuOpen || isSettingsOpen || isDead) return null;

  return (
    <div className="hotbar-wrapper">
      <div className="coin-display">
        ⚙ <span className="coin-amount">{coins}</span>
      </div>

      {activeReg && (
        <div className="active-item-name">
          {activeReg.name} {activeItem.count > 1 ? `(${activeItem.count})` : ''}
        </div>
      )}

      <div className="hotbar-container">
        <div className="hotbar-group blocks-group">
          {hotbarItems.map((item, idx) => {
            const color = item
              ? GlobalRegistry[item.texture]?.color || '#fff'
              : 'transparent';
            return (
              <div
                key={`hb-${idx}`}
                className={`hotbar-slot ${activeHotbarIndex === idx ? 'active' : ''}`}
                onClick={() => setActiveHotbarIndex(idx)}
              >
                <div className="hotbar-number">{idx + 1}</div>
                {item && (
                  <div
                    className="hotbar-icon"
                    style={{ backgroundColor: color }}
                  >
                    {item.count > 1 && (
                      <span className="item-count">{item.count}</span>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { useStore } from '../stores/useStore';
import * as THREE from 'three';

const MAX_LASERS = 50;
const LASER_GEO = new THREE.CylinderGeometry(0.05, 0.05, 1, 8);
// Rotate geometry so it points along Z axis instead of Y axis
LASER_GEO.rotateX(Math.PI / 2);
const LASER_MAT = new THREE.MeshBasicMaterial({
  color: '#00ffff',
  transparent: true,
  opacity: 0.8,
});
const _dummy = new THREE.Object3D();

export const Lasers = () => {
  const meshRef = useRef();

  useFrame(() => {
    if (!meshRef.current) return;
    const lasers = useStore.getState().lasers || [];

    // Hide all instances by default
    for (let i = 0; i < MAX_LASERS; i++) {
      _dummy.position.set(0, -1000 - i, 0);
      _dummy.scale.set(0, 0, 0);
      _dummy.updateMatrix();
      meshRef.current.setMatrixAt(i, _dummy.matrix);
    }

    let index = 0;
    for (const l of lasers) {
      if (index >= MAX_LASERS) break;

      const start = new THREE.Vector3(l.start[0], l.start[1], l.start[2]);
      const end = new THREE.Vector3(l.end[0], l.end[1], l.end[2]);

      const distance = start.distanceTo(end);
      if (distance < 0.001) continue;
      const midPoint = start.clone().lerp(end, 0.5);

      _dummy.position.copy(midPoint);
      _dummy.scale.set(1, 1, distance); // Scale Z to the distance
      _dummy.lookAt(end);
      _dummy.updateMatrix();

      meshRef.current.setMatrixAt(index, _dummy.matrix);
      index++;
    }

    meshRef.current.instanceMatrix.needsUpdate = true;
  });

  return (
    <instancedMesh
      ref={meshRef}
      args={[LASER_GEO, LASER_MAT, MAX_LASERS]}
      frustumCulled={false}
    />
  );
};

import React, { useRef, useEffect } from 'react';
import { useStore } from '../stores/useStore';
import {
  BlockRegistry,
  BlockById,
  BlockKeyById,
} from '../registry/BlockRegistry';
import {
  getIndex,
  getTextureId,
  getIsHidden,
  CHUNK_Y_MIN,
  CHUNK_Y_MAX,
} from '../utils/chunkData';
import { playerPosition, playerRotation } from '../globals';

// Precompute block colors for O(1) lightning-fast lookups in the minimap inner loop
const texColors = new Array(256).fill('#000000');
Object.keys(BlockById).forEach((id) => {
  texColors[id] = BlockById[id].color || '#ffffff';
});

export const Minimap = () => {
  const canvasRef = useRef(null);
  const mapContainerRef = useRef(null);
  const compassRingRef = useRef(null);
  const textRef = useRef(null);

  const nRef = useRef(null);
  const sRef = useRef(null);
  const eRef = useRef(null);
  const wRef = useRef(null);

  // Smoothly update rotation and coordinates without React state (zero lag)
  useEffect(() => {
    let frameId;
    let lastCoords = '';
    let lastYaw = null;

    const updateLoop = () => {
      // 1. Update Map Rotation
      if (mapContainerRef.current) {
        const yaw = playerRotation.y;

        if (yaw !== lastYaw) {
          mapContainerRef.current.style.transform = `rotate(${-yaw}rad)`;

          if (compassRingRef.current) {
            compassRingRef.current.style.transform = `rotate(${-yaw}rad)`;
          }

          // Counter-rotate the N, S, E, W markers so they stay perfectly upright
          if (nRef.current)
            nRef.current.style.transform = `translateX(-50%) rotate(${yaw}rad)`;
          if (sRef.current)
            sRef.current.style.transform = `translateX(-50%) rotate(${yaw}rad)`;
          if (eRef.current)
            eRef.current.style.transform = `translateY(-50%) rotate(${yaw}rad)`;
          if (wRef.current)
            wRef.current.style.transform = `translateY(-50%) rotate(${yaw}rad)`;

          lastYaw = yaw;
        }
      }

      // 2. Update Coordinates Text
      if (textRef.current) {
        const x = Math.floor(playerPosition.x);
        const y = Math.floor(playerPosition.y);
        const z = Math.floor(playerPosition.z);
        const newCoords = `X: ${x}  Y: ${y}  Z: ${z}`;

        // Only write to the DOM if the value actually changed to prevent layout thrashing
        if (newCoords !== lastCoords) {
          textRef.current.textContent = newCoords;
          lastCoords = newCoords;
        }
      }

      frameId = requestAnimationFrame(updateLoop);
    };
    updateLoop();
    return () => cancelAnimationFrame(frameId);
  }, []);

  // Update map scan every 5 seconds
  useEffect(() => {
    const scanMap = () => {
      const pos = playerPosition;
      const chunks = useStore.getState().chunks;

      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      ctx.clearRect(0, 0, 128, 128);

      const px = Math.floor(pos.x);
      const pxY = Math.floor(pos.y);
      const pz = Math.floor(pos.z);

      const radius = 32; // 32 blocks radius = 64x64 diameter

      for (let dx = -radius; dx <= radius; dx++) {
        for (let dz = -radius; dz <= radius; dz++) {
          const x = px + dx;
          const z = pz + dz;
          const cx = Math.floor(x / 16);
          const cz = Math.floor(z / 16);
          const chunkKey = `${cx},${cz}`;

          if (chunks[chunkKey]) {
            const buffer = chunks[chunkKey].buffer;
            let foundColor = null;
            if (buffer) {
              const lx = ((x % 16) + 16) % 16;
              const lz = ((z % 16) + 16) % 16;

              // Start scanning from Math.min(150, playerY + 40) down to -64 to skip empty sky
              const scanTop = Math.min(150, pxY + 40);
              let idx = lx + lz * 16 + (scanTop - CHUNK_Y_MIN) * 256;

              for (let y = scanTop; y > CHUNK_Y_MIN; y--) {
                const val = buffer[idx];
                if (val !== 0 && !(val & (1 << 21))) {
                  // Inline getIsHidden for speed
                  foundColor = texColors[val & 0xff]; // Inline getTextureId for speed
                  break;
                }
                idx -= 256;
              }
            }
            if (foundColor) {
              ctx.fillStyle = foundColor;
              ctx.fillRect((dx + radius) * 2, (dz + radius) * 2, 2, 2);
            }
          }
        }
      }

      // Draw player dot in center
      ctx.fillStyle = '#ff0055';
      ctx.beginPath();
      ctx.arc(radius * 2, radius * 2, 4, 0, Math.PI * 2);
      ctx.fill();
    };

    scanMap(); // Run immediately on mount so it's not blank!
    const interval = setInterval(scanMap, 5000); // update every 5 seconds

    return () => clearInterval(interval);
  }, []);

  return (
    <div
      style={{
        position: 'absolute',
        top: '20px',
        right: '20px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: '12px',
        zIndex: 10,
      }}
    >
      {/* Map & Compass Wrapper */}
      <div
        style={{
          position: 'relative',
          width: '160px',
          height: '160px',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
        }}
      >
        {/* Rotating Minimap */}
        <div
          ref={mapContainerRef}
          style={{
            width: '128px',
            height: '128px',
            borderRadius: '50%',
            overflow: 'hidden',
            border: '4px solid rgba(255, 255, 255, 0.1)',
            boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
            backgroundColor: 'rgba(15, 23, 42, 0.8)',
            backdropFilter: 'blur(8px)',
            position: 'absolute',
          }}
        >
          <canvas
            ref={canvasRef}
            width={128}
