import React, { useRef } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { useStore } from '../stores/useStore';
import * as THREE from 'three';

const TETHER_GEO = new THREE.CylinderGeometry(0.04, 0.04, 1, 8);
TETHER_GEO.rotateX(Math.PI / 2);
const TETHER_MAT = new THREE.MeshBasicMaterial({
  color: '#ffffff',
  transparent: true,
  opacity: 0.6,
});
const _dummy = new THREE.Object3D();

export const Tether = () => {
  const meshRef = useRef();
  const { camera } = useThree();

  useFrame(() => {
    if (!meshRef.current) return;
    const target = useStore.getState().grappleTarget;

    if (!target) {
      _dummy.position.set(0, -1000, 0);
      _dummy.scale.set(0, 0, 0);
      _dummy.updateMatrix();
      meshRef.current.setMatrixAt(0, _dummy.matrix);
      meshRef.current.instanceMatrix.needsUpdate = true;
      return;
    }

    const dir = new THREE.Vector3();
    camera.getWorldDirection(dir);

    // Approximate the visual start point at the barrel of the grapple gun
    let right = dir.clone().cross(camera.up);
    if (right.lengthSq() < 0.0001) right.set(1, 0, 0);
    right.normalize();

    const camWorldPos = new THREE.Vector3();
    camera.getWorldPosition(camWorldPos);

    const visualStart = camWorldPos.clone()
      .addScaledVector(dir, 0.4) // Forward
      .addScaledVector(camera.up, -0.3) // Down
      .addScaledVector(right, 0.2); // Right

    const end = new THREE.Vector3(target[0], target[1], target[2]);
    const distance = visualStart.distanceTo(end);

    if (distance > 0.001) {
      const midPoint = visualStart.clone().lerp(end, 0.5);
      _dummy.position.copy(midPoint);
      _dummy.scale.set(1, 1, distance);
      _dummy.lookAt(end);
      _dummy.updateMatrix();
      meshRef.current.setMatrixAt(0, _dummy.matrix);
      meshRef.current.instanceMatrix.needsUpdate = true;
    }
  });

  return (
    <instancedMesh
      ref={meshRef}
      args={[TETHER_GEO, TETHER_MAT, 1]}
      frustumCulled={false}
    />
  );
};

import { useStore } from '../stores/useStore';
import { playerPosition as globalPlayerPosition } from '../globals';
import { useNetworkStore } from '../stores/useNetworkStore';
import { RigidBody, CuboidCollider } from '@react-three/rapier';
import { Text } from '@react-three/drei';
import * as THREE from 'three';
import { useFrame } from '@react-three/fiber';
import { useRef } from 'react';

// A simple tombstone component
const TombstoneItem = ({ tombstone }) => {
  const meshRef = useRef();

  const handleLoot = () => {
    const state = useStore.getState();
    let toDrop = [];

    tombstone.inventory.forEach((item) => {
      if (item && item.texture) {
        const leftover = state.addInventoryItem(item.texture, item.count);
        if (leftover > 0) {
          toDrop.push({ texture: item.texture, count: leftover });
        }
      }
    });

    if (toDrop.length > 0) {
      const newDropped = [...(state.droppedItems || [])];
      toDrop.forEach((item) => {
        newDropped.push({
          key: Math.random().toString(36),
          texture: item.texture,
          count: item.count,
          pos: [
            tombstone.pos[0] + (Math.random() - 0.5),
            tombstone.pos[1] + 1,
            tombstone.pos[2] + (Math.random() - 0.5),
          ],
          pickupCooldown: Date.now() + 1000,
        });
      });
      useStore.setState({ droppedItems: newDropped });
    }

    useStore.getState().removeTombstone(tombstone.id);
    const netStore = useNetworkStore.getState();
    netStore.addChatMessage(
      `Looted ${tombstone.ownerName}'s Tombstone!`,
      'system',
      'System'
    );
    if (netStore.removeWaypoint) netStore.removeWaypoint('death_waypoint');
  };

  useFrame(() => {
    if (!meshRef.current) return;
    // Rotate slowly
    meshRef.current.rotation.y += 0.01;

    // Interaction check
    const px = globalPlayerPosition.x;
    const py = globalPlayerPosition.y;
    const pz = globalPlayerPosition.z;

    const dx = px - tombstone.pos[0];
    const dy = py - tombstone.pos[1];
    const dz = pz - tombstone.pos[2];
    const distSq = dx * dx + dy * dy + dz * dz;

    if (distSq < 4) {
      // Within 2 blocks
      handleLoot();
    }
  });

  return (
    <RigidBody
      position={tombstone.pos}
      colliders={false}
      type="dynamic"
      mass={1}
      lockRotations
    >
      <CuboidCollider args={[0.4, 0.5, 0.4]} />
      <group
        ref={meshRef}
        onClick={(e) => {
          e.stopPropagation();
          handleLoot();
        }}
      >
        <mesh castShadow receiveShadow position={[0, 0, 0]}>
          <boxGeometry args={[0.8, 1, 0.8]} />
          <meshStandardMaterial color="#444444" />
        </mesh>
        <Text
          position={[0, 0.51, 0]}
          rotation={[-Math.PI / 2, 0, 0]}
          fontSize={0.2}
          color="white"
          anchorX="center"
          anchorY="middle"
        >
          RIP
        </Text>
        <Text
          position={[0, 0.6, 0.41]}
          fontSize={0.15}
          color="white"
          anchorX="center"
          anchorY="middle"
        >
          {tombstone.ownerName}
        </Text>
      </group>
    </RigidBody>
  );
};

export const Tombstones = () => {
  const tombstones = useStore((state) => state.tombstones) || [];

  return (
    <group>
      {tombstones.map((tombstone) => (
        <TombstoneItem key={tombstone.id} tombstone={tombstone} />
      ))}
    </group>
  );
};

import React, { useRef, useState } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Billboard, Text } from '@react-three/drei';
import { useNetworkStore } from '../stores/useNetworkStore';

export const Waypoints = () => {
  const waypoints = useNetworkStore((state) => state.waypoints);
  const [activeWaypoints, setActiveWaypoints] = useState([]);
  const { camera } = useThree();

  useFrame(() => {
    const now = Date.now();
    const valid = waypoints.filter((w) => now - w.timestamp < 10000);

    if (valid.length !== activeWaypoints.length) {
      setActiveWaypoints(valid);
    } else {
      let changed = false;
      for (let i = 0; i < valid.length; i++) {
        if (
          valid[i].id !== activeWaypoints[i]?.id ||
          valid[i].timestamp !== activeWaypoints[i]?.timestamp
        ) {
          changed = true;
          break;
        }
      }
      if (changed) setActiveWaypoints(valid);
    }
  });

  return (
    <group>
      {activeWaypoints.map((w) => (
        <WaypointMarker
          key={`${w.id}-${w.timestamp}`}
          waypoint={w}
          camera={camera}
        />
      ))}
    </group>
  );
};

const WaypointMarker = ({ waypoint, camera }) => {
  const meshRef = useRef();
  const [distance, setDistance] = useState(0);
  const [opacity, setOpacity] = useState(1);

  useFrame(() => {
    if (meshRef.current) {
      const dist = camera.position.distanceTo(meshRef.current.position);
      setDistance(Math.round(dist));
      const scale = Math.max(1, dist / 15);
      meshRef.current.scale.set(scale, scale, scale);
    }

    const age = Date.now() - waypoint.timestamp;
    if (age > 8000) {
      setOpacity(Math.max(0, 1 - (age - 8000) / 2000));
    } else {
      setOpacity(1);
    }
  });

  return (
    <Billboard
      ref={meshRef}
      position={[waypoint.x, waypoint.y + 0.5, waypoint.z]}
    >
      <Text
        position={[0, 0.4, 0]}
        fontSize={0.5}
        color={waypoint.color}
        outlineWidth={0.05}
        outlineColor="black"
        anchorX="center"
        anchorY="middle"
        depthTest={false}
        fillOpacity={opacity}
        outlineOpacity={opacity}
      >
        ▼
      </Text>
      <Text
        position={[0, -0.1, 0]}
        fontSize={0.25}
        color={waypoint.color}
        outlineWidth={0.03}
        outlineColor="black"
        anchorX="center"
        anchorY="middle"
        depthTest={false}
        fillOpacity={opacity}
        outlineOpacity={opacity}
      >
        {distance}m
      </Text>
    </Billboard>
  );
};

